		lights.addComponent(al1);
		var t = minko_utils_MathUtil.sphericalRand(100.0);
		var this1 = new glm_Mat4Base();
		this1._00 = 0;
		this1._01 = 0;
		this1._02 = 0;
		this1._03 = 0;
