		this1._31 = 0;
		this1._32 = 0;
		this1._33 = 0;
		var dest = this1;
		dest._00 = 1;
		dest._10 = 0;
		dest._20 = 0;
		dest._30 = 0;
		dest._01 = 0;
		dest._11 = 1;
		dest._21 = 0;
		dest._31 = 0;
		dest._02 = 0;
		dest._12 = 0;
		dest._22 = 1;
		dest._32 = 0;
		dest._03 = 0;
