	,testSurfaceSetNewMaterialWithProgramForking: function() {
		var node = minko_scene_Node.create("a");
		var diffuseMap = minko_render_Texture.create(this._sceneManager.get_canvas().get_context(),32,32);
		diffuseMap.upload();
		node.addComponent(minko_component_Surface.create(this._sceneManager.get_assets().geometry("cube"),this._sceneManager.get_assets().material("red"),this._sceneManager.get_assets().effect("effect/Basic.effect")));
		this._sceneManager.nextFrame(0.0,0.0);
		var newMaterial = minko_material_Material.createbyMaterial(this._sceneManager.get_assets().material("red"));
		newMaterial.get_data().set("diffuseMap",diffuseMap);
		var surface = node.getComponent(minko_component_Surface);
		surface.set_material(newMaterial);
		this._sceneManager.nextFrame(0.0,0.0);
		this.assertTrue(true,{ fileName : "minko-hx/src/test/component/SurfaceTest.hx", lineNumber : 259, className : "test.component.SurfaceTest", methodName : "testSurfaceSetNewMaterialWithProgramForking"});
	}
